class Node:

	def __init__(self, val):
		self.right = None
		self.data = val
		self.left = None
		self.next = None

class Solution:

	def inorder(self, root, prev):
		if root is None:
			return
		self.inorder(root.left, prev)
		prev[0].next = root
		prev[0] = root
		self.inorder(root.right, prev)

	def populateNext(self, root):
		dummy = Node(-1)
		prev = [dummy]
		self.inorder(root, prev)
		return dummy.next
